/* ============================================================================
   billnow-flow  —  Legacy 3-step flow (stands down beside the native checkout)
   ============================================================================ */

/* ============================================================================
   Billnaw — billing flow  v1.0
   Load after billnow-brand.js.

   The billing screen asked for everything at once: items, customer, discounts,
   payment, and a six-row totals block that sat below the fold. On a phone a
   clerk scrolled past the thing they were doing to reach the thing they needed.

   Three steps instead, each one screen:
     1 ITEMS     scan or search, basket grows, nothing else on screen
     2 CUSTOMER  who is this for, and how are they paying
     3 REVIEW    what will print, what is owed, and the print button

   A floating bar carries the running total and moves you forward. The inline
   totals block is hidden only once this script has taken over, so a failure
   here leaves the original screen intact.
   ========================================================================== */
(function () {
'use strict';

if (!window.matchMedia('(max-width: 900px)').matches) return;

/* The app ships its own checkout: #checkoutFab -> openCheckout() -> a modal
   with items, totals, UPI QR, amount paid and Save & Print. This layer was
   written without noticing it, and the result was two floating bars over a
   third. Stand down entirely when the native one is present. */
if (document.getElementById('checkoutFab')) return;

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
const inr = (v) => '₹' + num(v).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const $ = (id) => document.getElementById(id);
const lines = () => (typeof currentInvoice !== 'undefined' ? currentInvoice : []);

const STEPS = [
  { k: 'items', label: 'Items' },
  { k: 'customer', label: 'Customer' },
  { k: 'review', label: 'Review' },
];
let step = 'items';

const onBilling = () => {
  const v = document.querySelector('.view-section.active-view');
  return !!v && v.id === 'billing';
};

/* --------------------------------------------------------------------------
   Totals — read from the app's own figures so the bar and the bill agree
   ------------------------------------------------------------------------ */
function totals() {
  const t = (window.BillNowSheet && window.BillNowSheet.totals)
    ? window.BillNowSheet.totals()
    : { taxable: 0, gst: 0, grand: 0, paid: 0, oldGold: 0, due: 0 };
  return t;
}

/* --------------------------------------------------------------------------
   1.  STEP BAR
   ------------------------------------------------------------------------ */
function buildStepBar() {
  const view = $('billing');
  if (!view || $('bnSteps')) return;
  const bar = document.createElement('div');
  bar.id = 'bnSteps';
  bar.className = 'bn-steps no-print';
  bar.innerHTML = STEPS.map((s, i) =>
    `<button type="button" data-step="${s.k}"><i>${i + 1}</i><span>${s.label}</span></button>`).join('');
  const head = view.querySelector('.header-top');
  (head || view.firstElementChild).insertAdjacentElement('afterend', bar);

  bar.addEventListener('click', (e) => {
    const b = e.target.closest('[data-step]');
    if (!b) return;
    if (b.dataset.step !== 'items' && !lines().length) {
      if (window.bnToast) window.bnToast('Add an item first');
      return;
    }
    goStep(b.dataset.step);
  });
}

/* --------------------------------------------------------------------------
   2.  PANELS — the customer and review steps are built here; the items step
       is the app's own markup, simply left alone.
   ------------------------------------------------------------------------ */
function buildPanels() {
  const view = $('billing');
  if (!view || $('bnCustPanel')) return;

  const cust = document.createElement('div');
  cust.id = 'bnCustPanel';
  cust.className = 'bn-step-panel no-print';
  cust.hidden = true;
  cust.innerHTML = `
    <div class="bn-field"><label for="bnCName">Customer name</label>
      <input type="text" id="bnCName" placeholder="Cash Customer" autocomplete="name"></div>
    <div class="bn-field"><label for="bnCPhone">Phone</label>
      <input type="tel" id="bnCPhone" inputmode="tel" placeholder="10 digits"></div>
    <div class="bn-field"><label for="bnCGst">GSTIN <span>optional</span></label>
      <input type="text" id="bnCGst" placeholder="For a B2B bill"></div>
    <div class="bn-field"><label for="bnCAddr">Address <span>optional</span></label>
      <input type="text" id="bnCAddr" placeholder="Prints on the invoice"></div>
    <div class="bn-field"><label>Payment mode</label>
      <div class="bn-pay" id="bnPayModes">
        ${['Cash', 'UPI', 'Card', 'Credit'].map((m) =>
          `<button type="button" data-pay="${m}"${m === 'Cash' ? ' class="on"' : ''}>${m}</button>`).join('')}
      </div></div>
    <div class="bn-recent" id="bnRecentCust"></div>`;
  view.appendChild(cust);

  const rev = document.createElement('div');
  rev.id = 'bnReviewPanel';
  rev.className = 'bn-step-panel no-print';
  rev.hidden = true;
  view.appendChild(rev);

  cust.addEventListener('click', (e) => {
    const p = e.target.closest('[data-pay]');
    if (p) {
      cust.querySelectorAll('[data-pay]').forEach((b) => b.classList.toggle('on', b === p));
      const sel = $('billPaymentMode');
      if (sel) { sel.value = p.dataset.pay; sel.dispatchEvent(new Event('change', { bubbles: true })); }
      // Credit means nothing received yet; anything else defaults to paid in full.
      const paid = $('billAmountPaid');
      if (paid) {
        paid.value = p.dataset.pay === 'Credit' ? '' : totals().grand.toFixed(2);
        paid.dispatchEvent(new Event('input', { bubbles: true }));
        if (typeof calculateDue === 'function') calculateDue();
      }
      return;
    }
    const r = e.target.closest('[data-cust]');
    if (r) {
      $('bnCName').value = r.dataset.cust;
      $('bnCPhone').value = r.dataset.phone || '';
      mirrorCustomer();
    }
  });
  cust.addEventListener('input', mirrorCustomer);
}

/** Write the step-2 fields back into the app's own inputs, which every other
 *  part of the system reads. This panel is a nicer face on the same form. */
function mirrorCustomer() {
  const map = [['bnCName', 'customerName'], ['bnCPhone', 'customerPhone'],
               ['bnCGst', 'customerGstin'], ['bnCAddr', 'customerAddress']];
  map.forEach(([from, to]) => {
    const a = $(from), b = $(to);
    if (a && b && b.value !== a.value) {
      b.value = a.value;
      b.dispatchEvent(new Event('input', { bubbles: true }));
      b.dispatchEvent(new Event('change', { bubbles: true }));
    }
  });
  if (typeof autoFillCustomer === 'function') { try { autoFillCustomer(); } catch (e) {} }
}

function paintRecent() {
  const host = $('bnRecentCust');
  if (!host) return;
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];
  const seen = new Map();
  for (let i = hist.length - 1; i >= 0 && seen.size < 6; i--) {
    const n = String(hist[i].customer || '').trim();
    if (!n || n.toLowerCase() === 'cash customer' || seen.has(n)) continue;
    seen.set(n, hist[i].phone || '');
  }
  host.innerHTML = seen.size
    ? `<div class="bn-recent-label">Recent</div>` + [...seen].map(([n, p]) =>
        `<button type="button" data-cust="${esc(n)}" data-phone="${esc(p)}">${esc(n)}</button>`).join('')
    : '';
}

function paintReview() {
  const host = $('bnReviewPanel');
  if (!host) return;
  const t = totals();
  const L = lines();
  const paid = $('billAmountPaid');
  const mode = ($('billPaymentMode') || {}).value || 'Cash';

  host.innerHTML = `
    <div class="bn-rev-lines">
      ${L.map((l) => `
        <div class="bn-rev-line">
          <span class="nm">${esc(l.name)}</span>
          <span class="qt">${num(l.netWt) > 0 ? num(l.netWt) + 'g' : num(l.qty)} × ${inr(l.rate)}</span>
          <span class="am">${inr(l.total)}</span>
        </div>`).join('') || '<div class="bn-empty">No items on this bill.</div>'}
    </div>
    <div class="bn-rev-sum">
      <div><span>Taxable</span><b>${inr(t.taxable)}</b></div>
      <div><span>GST</span><b>${inr(t.gst)}</b></div>
      ${t.roundOff ? `<div><span>Round off</span><b>${inr(t.roundOff)}</b></div>` : ''}
    </div>
    <div class="bn-rev-total"><span>Net payable</span><strong>${inr(t.grand)}</strong></div>
    <div class="bn-field bn-rev-paid">
      <label for="bnPaid">Received now <span>${esc(mode)}</span></label>
      <input type="text" id="bnPaid" inputmode="decimal" value="${paid && paid.value ? esc(paid.value) : ''}"
             placeholder="Leave blank for credit">
    </div>
    <div class="bn-rev-bal" data-state="${t.due > 0.004 ? 'due' : t.due < -0.004 ? 'change' : 'settled'}">
      <span>${t.due > 0.004 ? 'Balance due' : t.due < -0.004 ? 'Change to return' : 'Settled'}</span>
      <strong>${inr(Math.abs(t.due))}</strong>
    </div>`;

  const p = $('bnPaid');
  if (p) p.addEventListener('input', () => {
    const real = $('billAmountPaid');
    if (real) {
      real.value = p.value;
      real.dispatchEvent(new Event('input', { bubbles: true }));
      if (typeof calculateDue === 'function') calculateDue();
    }
    paintBar(); paintReviewBalanceOnly();
  });
}

/* Repaint only the balance so typing does not rebuild the field under the caret. */
function paintReviewBalanceOnly() {
  const el = document.querySelector('.bn-rev-bal');
  if (!el) return;
  const t = totals();
  el.dataset.state = t.due > 0.004 ? 'due' : t.due < -0.004 ? 'change' : 'settled';
  el.querySelector('span').textContent =
    t.due > 0.004 ? 'Balance due' : t.due < -0.004 ? 'Change to return' : 'Settled';
  el.querySelector('strong').textContent = inr(Math.abs(t.due));
}

/* --------------------------------------------------------------------------
   3.  FLOATING BAR
   ------------------------------------------------------------------------ */
function buildBar() {
  // mobile.js may already have built its own bar before this file loaded.
  const stale = $('bnBillBar');
  if (stale) stale.remove();
  if ($('bnFlowBar')) return;
  const bar = document.createElement('div');
  bar.id = 'bnFlowBar';
  bar.className = 'bn-flowbar no-print';
  bar.hidden = true;
  bar.innerHTML = `
    <div class="bn-flowbar-left">
      <small id="bnFlowLabel">Net payable</small>
      <strong id="bnFlowTotal">₹0.00</strong>
      <em id="bnFlowMeta"></em>
    </div>
    <button type="button" id="bnFlowGo">Next</button>`;
  document.body.appendChild(bar);
  $('bnFlowGo').addEventListener('click', advance);
}

function advance() {
  if (step === 'items') {
    if (!lines().length) { if (window.bnToast) window.bnToast('Add an item first'); return; }
    return goStep('customer');
  }
  if (step === 'customer') { mirrorCustomer(); return goStep('review'); }
  // review -> print
  if (typeof finalizeAndPrintInvoice === 'function') finalizeAndPrintInvoice();
  setTimeout(() => goStep('items'), 600);
}

function paintBar() {
  const bar = $('bnFlowBar');
  if (!bar) return;
  const show = onBilling() && (lines().length > 0 || step !== 'items');
  bar.hidden = !show;
  if (!show) return;

  const t = totals();
  $('bnFlowTotal').textContent = inr(t.grand);
  $('bnFlowLabel').textContent = step === 'review' ? 'Net payable' : 'Running total';
  const n = lines().length;
  $('bnFlowMeta').textContent = n ? `${n} item${n === 1 ? '' : 's'}` : '';
  $('bnFlowGo').textContent = step === 'review' ? 'Save & print' : 'Next';
  $('bnFlowGo').classList.toggle('go', step === 'review');
}

/* --------------------------------------------------------------------------
   4.  STEP SWITCHING
   ------------------------------------------------------------------------ */
function itemsNodes() {
  const view = $('billing');
  if (!view) return [];
  return Array.from(view.children).filter((el) =>
    !['bnSteps', 'bnCustPanel', 'bnReviewPanel'].includes(el.id) &&
    !el.classList.contains('print-only') && !el.classList.contains('header-top'));
}

function goStep(k) {
  step = k;
  const view = $('billing');
  if (!view) return;

  itemsNodes().forEach((el) => { el.style.display = k === 'items' ? '' : 'none'; });
  const c = $('bnCustPanel'), r = $('bnReviewPanel');
  if (c) c.hidden = k !== 'customer';
  if (r) r.hidden = k !== 'review';

  document.querySelectorAll('#bnSteps [data-step]').forEach((b) => {
    const i = STEPS.findIndex((s) => s.k === b.dataset.step);
    const cur = STEPS.findIndex((s) => s.k === k);
    b.classList.toggle('on', b.dataset.step === k);
    b.classList.toggle('done', i < cur);
  });

  if (k === 'customer') { paintRecent(); syncFromApp(); }
  if (k === 'review') paintReview();
  paintBar();
  try { window.scrollTo(0, 0); } catch (e) {}
}

/** Pull whatever the app already holds into the step-2 fields. */
function syncFromApp() {
  [['customerName', 'bnCName'], ['customerPhone', 'bnCPhone'],
   ['customerGstin', 'bnCGst'], ['customerAddress', 'bnCAddr']].forEach(([from, to]) => {
    const a = $(from), b = $(to);
    if (a && b && !b.value) b.value = a.value || '';
  });
}

/* --------------------------------------------------------------------------
   BOOT
   ------------------------------------------------------------------------ */
function refresh() {
  if (!onBilling()) { const b = $('bnFlowBar'); if (b) b.hidden = true; return; }
  buildStepBar(); buildPanels(); buildBar();
  if (step === 'review') paintReview();
  paintBar();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnFlowWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw flow]', e.message); }
    return r;
  };
  fn.__bnFlowWrapped = true;
  window[name] = fn;
}

function boot() {
  buildStepBar(); buildPanels(); buildBar();
  goStep('items');
  // Only now may CSS hide the original totals block.
  document.documentElement.classList.add('bn-flow-ready');
  ['renderInvoiceTable', 'calculateDue', 'switchView', 'clearBillingCart', 'updateIndustry']
    .forEach((n) => wrap(n, refresh));
  wrap('clearBillingCart', () => goStep('items'));
}

window.BillnawFlow = { goStep, get step() { return step; }, totals, paintBar, advance };

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-picker  —  Product picker, shop logo, grouped settings
   ============================================================================ */

/* ============================================================================
   Billnaw — billing picker, shop logo & settings grouping  v1.0
   Load after billnow-flow.js.

   Three problems the screenshots showed, in order of cost to the shopkeeper:

   1. Choosing an item meant opening a native <select> and scrolling a list with
      no stock, no price and no way to bill something that is not in stock
      without leaving the flow.
   2. There was nowhere to put the shop logo, even though app.js already stores
      one in shopSettings.logoData and prints it on the invoice.
   3. Settings was one long column of unrelated fields.
   ========================================================================== */
(function () {
'use strict';

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
const inr = (v) => '₹' + num(v).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const $ = (id) => document.getElementById(id);
const MOBILE = () => window.matchMedia('(max-width: 900px)').matches;

const stock = () => {
  const sel = $('industrySelector');
  const ind = sel && sel.value;
  const inv = (typeof isolatedInventory !== 'undefined' ? isolatedInventory : window.isolatedInventory) || {};
  return (ind && inv[ind]) || [];
};

/* ==========================================================================
   1.  PRODUCT PICKER — what is on the shelf, with a way out for what is not
   ========================================================================== */
function buildPicker() {
  const nameField = $('billItemName');
  if (!nameField || $('bnPicker')) return;

  const host = document.createElement('div');
  host.id = 'bnPicker';
  host.className = 'bn-picker no-print';
  host.innerHTML = `
    <input type="search" id="bnPickSearch" class="bn-pick-search"
           placeholder="Search stock, or scan" autocomplete="off" enterkeyhint="search">
    <div class="bn-pick-list" id="bnPickList"></div>
    <button type="button" class="bn-pick-manual" id="bnPickManual">
      Item not in stock — enter it manually
    </button>`;

  // Sit above the app's own item form; that form becomes the manual path.
  const group = nameField.closest('.form-group') || nameField.parentElement;
  group.insertAdjacentElement('beforebegin', host);
  group.classList.add('bn-manual-form');

  $('bnPickSearch').addEventListener('input', paintPicker);
  $('bnPickManual').addEventListener('click', () => {
    document.body.classList.toggle('bn-manual-open');
    const on = document.body.classList.contains('bn-manual-open');
    $('bnPickManual').textContent = on
      ? 'Back to stock list'
      : 'Item not in stock — enter it manually';
    if (on) nameField.focus();
  });

  host.addEventListener('click', (e) => {
    const b = e.target.closest('[data-pick]');
    if (!b) return;
    pick(b.dataset.pick);
  });

  paintPicker();
}

/** Fill the app's own inputs, then let its own addInvoiceItem do the work. */
function pick(name) {
  const it = stock().find((i) => i.name === name);
  if (!it) return;
  const set = (id, v) => {
    const el = $(id);
    if (!el || v == null || v === '') return;
    el.value = v;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  set('billItemName', it.name);
  set('billRate', it.price);
  set('billGst', it.gst);
  set('billHsn', it.hsn);
  set('billBatch', it.batch);
  set('billExpiry', it.expiry);
  set('billPurity', it.purity);
  set('billQty', 1);

  if (typeof autoFillItem === 'function') { try { autoFillItem(); } catch (e) {} }
  if (typeof addInvoiceItem === 'function') addInvoiceItem();

  const s = $('bnPickSearch');
  if (s) { s.value = ''; paintPicker(); s.focus(); }
  if (window.bnToast) window.bnToast(it.name + ' added');
}

function paintPicker() {
  const list = $('bnPickList');
  if (!list) return;
  const q = ($('bnPickSearch').value || '').trim().toLowerCase();
  let items = stock();
  if (q) {
    items = items.filter((i) =>
      String(i.name || '').toLowerCase().includes(q) ||
      String(i.batch || '').toLowerCase().includes(q) ||
      String(i.hsn || '').toLowerCase().includes(q));
  }
  items = items.slice(0, 40);

  if (!items.length) {
    list.innerHTML = `<div class="bn-empty">${q ? 'Nothing in stock matches that.' : 'No stock yet — add products first.'}</div>`;
    return;
  }

  list.innerHTML = items.map((i) => {
    const q0 = num(i.qty);
    const state = q0 <= 0 ? 'out' : q0 <= 5 ? 'low' : 'ok';
    return `<button type="button" class="bn-pick" data-pick="${esc(i.name)}" data-state="${state}">
      <span class="nm">${esc(i.name)}</span>
      <span class="mt">${inr(i.price)}${i.gst ? ' · ' + esc(i.gst) + '% GST' : ''}</span>
      <span class="qt">${q0}<small>${state === 'out' ? 'out' : 'left'}</small></span>
    </button>`;
  }).join('');
}

/* ==========================================================================
   2.  SHOP LOGO — app.js already stores and prints shopSettings.logoData;
       there was simply no way to put one in.
   ========================================================================== */
function buildLogoField() {
  const panel = document.querySelector('#settings .settings-panel');
  if (!panel || $('bnLogoField')) return;

  const sec = document.createElement('div');
  sec.id = 'bnLogoField';
  sec.className = 'bn-set-block';
  sec.dataset.group = 'shop';
  sec.innerHTML = `
    <h3>Shop logo</h3>
    <p class="bn-note">Prints at the top of every invoice. A square PNG around
      512&nbsp;px works best; it is stored on this device only.</p>
    <div class="bn-logo-row">
      <div class="bn-logo-prev" id="bnLogoPrev"><span>No logo</span></div>
      <div class="bn-logo-acts">
        <label class="btn-info bn-logo-pick" for="bnLogoInput">Choose image</label>
        <input type="file" id="bnLogoInput" accept="image/png,image/jpeg,image/webp" hidden>
        <button type="button" class="btn-warning" id="bnLogoClear">Remove</button>
      </div>
    </div>`;
  panel.insertBefore(sec, panel.firstChild);

  $('bnLogoInput').addEventListener('change', (e) => {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    if (f.size > 2 * 1024 * 1024) { alert('Please pick an image under 2 MB.'); return; }
    const r = new FileReader();
    r.onload = () => {
      // Downscale before storing: a 4 MB camera photo in localStorage is how
      // people hit the quota and lose data.
      const img = new Image();
      img.onload = () => {
        const n = 512, c = document.createElement('canvas');
        c.width = c.height = n;
        const ctx = c.getContext('2d');
        const s = Math.min(n / img.width, n / img.height);
        const w = img.width * s, h = img.height * s;
        ctx.drawImage(img, (n - w) / 2, (n - h) / 2, w, h);
        const data = c.toDataURL('image/png');
        if (typeof shopSettings === 'object') shopSettings.logoData = data;
        try {
          const cur = JSON.parse(localStorage.getItem('myBusinessSettings') || '{}');
          cur.logoData = data;
          localStorage.setItem('myBusinessSettings', JSON.stringify(cur));
        } catch (err) { alert('Could not save the logo: ' + err.message); return; }
        paintLogoPreview();
        if (typeof updatePrintDOM === 'function') updatePrintDOM();
        if (window.bnToast) window.bnToast('Logo saved');
      };
      img.onerror = () => alert('That file could not be read as an image.');
      img.src = r.result;
    };
    r.readAsDataURL(f);
  });

  $('bnLogoClear').addEventListener('click', () => {
    if (typeof shopSettings === 'object') shopSettings.logoData = '';
    try {
      const cur = JSON.parse(localStorage.getItem('myBusinessSettings') || '{}');
      cur.logoData = '';
      localStorage.setItem('myBusinessSettings', JSON.stringify(cur));
    } catch (e) {}
    paintLogoPreview();
    if (window.bnToast) window.bnToast('Logo removed');
  });

  paintLogoPreview();
}

function paintLogoPreview() {
  const p = $('bnLogoPrev');
  if (!p) return;
  const d = (typeof shopSettings === 'object' && shopSettings.logoData) || '';
  p.innerHTML = d ? `<img src="${d}" alt="Shop logo">` : '<span>No logo</span>';
}

/* ==========================================================================
   3.  SETTINGS GROUPING — one long column became sections
   ========================================================================== */
const GROUPS = [
  { k: 'shop', label: 'Shop & identity', match: /shop|logo|address|gstin|gst no|bank|upi|terms|jurisdiction|licence|license|bis|warranty|invoice details/i },
  { k: 'print', label: 'Printing', match: /print|paper|printer|bluetooth|invoice layout|thermal|copies/i },
  { k: 'data', label: 'Data & backup', match: /backup|restore|data|sync|cloud|export|import|wipe|reset/i },
  { k: 'advanced', label: 'Advanced', match: /ai|api|licence key|license key|master|developer/i },
];

function groupSettings() {
  const panel = document.querySelector('#settings .settings-panel');
  if (!panel || panel.dataset.bnGrouped) return;
  panel.dataset.bnGrouped = '1';

  /* The panel opens with shop-name, phone and address fields BEFORE the first
     <h3>. Grouping only on headings orphaned all of them, so the first block
     is created up front and collects everything until a heading appears. */
  const kids = Array.from(panel.children);
  let block = null;

  const startBlock = (groupKey, before) => {
    const b = document.createElement('section');
    b.className = 'bn-set-block';
    b.dataset.group = groupKey;
    before.insertAdjacentElement('beforebegin', b);
    return b;
  };

  kids.forEach((el) => {
    // Blocks made elsewhere (the logo field) are already grouped.
    if (el.classList && el.classList.contains('bn-set-block')) { block = null; return; }

    /* Sections injected by the add-ons (Bluetooth printer, invoice layout,
       per-trade invoice details) wrap their heading inside a <div>, so testing
       only for a direct H3 child missed every one of them and they were folded
       into whatever block happened to be open. */
    const ownHeading = el.tagName === 'H3'
      ? el
      : (el.querySelector && el.querySelector(':scope > h3'));

    if (ownHeading) {
      const label = (ownHeading.textContent || '').trim();
      const g = GROUPS.find((x) => x.match.test(label));
      block = startBlock(g ? g.k : 'other', el);
      block.appendChild(el);
      // A wrapper carries its own section; the next sibling starts fresh.
      if (el.tagName !== 'H3') block = null;
      return;
    }
    if (!block) block = startBlock('shop', el);   // leading, heading-less fields
    block.appendChild(el);
  });

  const present = [...GROUPS, { k: 'other', label: 'Other' }]
    .filter((g) => panel.querySelector(`.bn-set-block[data-group="${g.k}"]`));
  if (present.length < 2) return;

  const tabs = document.createElement('div');
  tabs.className = 'bn-set-tabs no-print';
  tabs.innerHTML = present.map((g, i) =>
    `<button type="button" data-group="${g.k}"${i === 0 ? ' class="on"' : ''}>${esc(g.label)}</button>`).join('');
  panel.insertAdjacentElement('beforebegin', tabs);

  tabs.addEventListener('click', (e) => {
    const b = e.target.closest('[data-group]');
    if (!b) return;
    tabs.querySelectorAll('[data-group]').forEach((x) => x.classList.toggle('on', x === b));
    showGroup(b.dataset.group);
  });
  showGroup(present[0].k);
}

function showGroup(k) {
  document.querySelectorAll('#settings .bn-set-block').forEach((b) => {
    b.hidden = b.dataset.group !== k;
  });
}

/* ==========================================================================
   BOOT
   ========================================================================== */
function refresh() {
  if (MOBILE()) buildPicker();
  buildLogoField();
  groupSettings();
  paintPicker();
  paintLogoPreview();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnPickWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw picker]', e.message); }
    return r;
  };
  fn.__bnPickWrapped = true;
  window[name] = fn;
}

function boot() {
  refresh();
  ['switchView', 'updateIndustry', 'renderInventoryTable', 'renderInvoiceTable', 'loadSettings']
    .forEach((n) => wrap(n, refresh));
  setTimeout(refresh, 500);
}

window.BillnawPicker = { paintPicker, pick, refresh, showGroup, GROUPS };

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-pro  —  Print isolation, paid-in-full, printer setup, Rule 46
   ============================================================================ */

/* ============================================================================
   Billnaw — pro fixes  v1.0
   Load last.

   Four defects visible in the screenshots, plus the compliance gaps a GST
   invoice cannot ship without.
   ========================================================================== */
(function () {
'use strict';

const $ = (id) => document.getElementById(id);
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

/* --------------------------------------------------------------------------
   1.  THE INVOICE PRINTED TWICE

   The PDF showed an orphaned item table and a Scan-to-Pay box above the real
   invoice. Cause: every other view carries class="no-print", but
   <div id="billing" class="view-section"> does not — so the live billing
   screen printed, and the sheet printed under it.

   The previous guard only hid .print-only elements, and the billing table is
   not one. Hiding every top-level sibling of the sheet is exact and cannot be
   defeated by a class that was never applied.
   ------------------------------------------------------------------------ */
function isolatePrint() {
  if ($('bnPrintIsolate')) return;
  const st = document.createElement('style');
  st.id = 'bnPrintIsolate';
  st.textContent = `
    @media print {
      body.bn-sheet > * { display: none !important; }
      body.bn-sheet > #bnInvoiceSheet { display: block !important; }
      body.bn-sheet #bnInvoiceSheet * { visibility: visible !important; }
    }`;
  document.head.appendChild(st);
}

/* --------------------------------------------------------------------------
   2.  ONE FLOATING BAR, WHATEVER ELSE IS ON THE PAGE

   The screenshot still showed a "RUNNING TOTAL" bar behind a green Checkout
   pill. Rather than naming the other bar — which may come from code this file
   has never seen — find every fixed element pinned to the bottom and keep the
   one the flow layer owns.
   ------------------------------------------------------------------------ */
function dedupeBottomBars() {
  const mine = $('bnFlowBar');
  if (!mine) return;
  const bars = Array.from(document.querySelectorAll('body > div, body > footer'))
    .filter((el) => {
      if (el === mine || el.id === 'bnPrintIsolate') return false;
      if (el.closest('#bnInvoiceSheet')) return false;
      const cs = getComputedStyle(el);
      if (cs.position !== 'fixed' || cs.display === 'none') return false;
      const b = parseFloat(cs.bottom);
      if (!Number.isFinite(b) || b > 200) return false;
      // A nav bar is a row of links; a checkout bar shows money.
      const t = el.textContent || '';
      return /checkout|total|payable|₹/i.test(t) && !el.classList.contains('bottom-nav');
    });
  bars.forEach((el) => {
    el.dataset.bnSuppressed = '1';
    el.style.display = 'none';
  });
}

/* --------------------------------------------------------------------------
   3.  CAMERA SCAN — the picker replaced the form that held the scan button
   ------------------------------------------------------------------------ */
function addScanButton() {
  const search = $('bnPickSearch');
  if (!search || $('bnScanBtn')) return;

  // Find whatever the app already uses to open the camera; do not reinvent it.
  const source = Array.from(document.querySelectorAll('#billing button, #billing a'))
    .find((b) => /scan/i.test(b.textContent || '') && /camera|barcode|qr/i.test(b.textContent || ''));

  const row = document.createElement('div');
  row.className = 'bn-scan-row no-print';
  row.innerHTML = `<button type="button" id="bnScanBtn" class="bn-scan-btn">
      <span aria-hidden="true">▣</span> Scan barcode with camera
    </button>`;
  search.insertAdjacentElement('afterend', row);

  $('bnScanBtn').addEventListener('click', () => {
    if (source) { source.click(); return; }
    for (const fn of ['startBarcodeScan', 'openScanner', 'scanBarcode', 'startScanner']) {
      if (typeof window[fn] === 'function') { window[fn](); return; }
    }
    alert('Camera scanning is not available in this browser.\n\nUse Chrome on Android over https, and allow camera access.');
  });
}

/* --------------------------------------------------------------------------
   3b. PAYMENT MODE

   Nothing in the markup records how the customer paid. The flow panel, the
   invoice renderer and the saved bill each reached for #billPaymentMode and
   found nothing, so every bill printed "Cash". One hidden field, created once,
   gives them a single source.
   ------------------------------------------------------------------------ */
function ensurePayMode() {
  if ($('billPaymentMode')) return;
  const anchor = $('billAmountPaid');
  if (!anchor) return;
  const el = document.createElement('input');
  el.type = 'hidden';
  el.id = 'billPaymentMode';
  el.value = localStorage.getItem('billnowLastPayMode') || 'Cash';
  anchor.insertAdjacentElement('afterend', el);
  el.addEventListener('change', () => {
    try { localStorage.setItem('billnowLastPayMode', el.value); } catch (e) {}
  });
}

/* --------------------------------------------------------------------------
   4.  DESKTOP TOTALS — slim, and paid-in-full by default

   The dark panel dominated the billing screen and left "Received now" empty,
   so a clerk typed the full amount on almost every bill. Most customers pay in
   full; make that the default and let the exception be typed.
   ------------------------------------------------------------------------ */
let autofillArmed = true;

function autofillPaid() {
  const paid = $('billAmountPaid');
  const grand = $('grandTotal');
  if (!paid || !grand) return;
  const total = num(grand.innerText || grand.textContent);
  if (total <= 0) return;

  // Fill an EMPTY field only. Anything already in there - typed by the clerk,
  // restored from a draft, or written by another part of the app - is somebody
  // else's number, and silently replacing it is a money error.
  if (String(paid.value).trim() !== '') return;
  if (paid.dataset.bnUserEdited === '1') return;
  const mode = ($('billPaymentMode') || {}).value || '';
  if (/credit/i.test(mode)) return;
  if (!autofillArmed) return;
  paid.value = total.toFixed(2);
  paid.dispatchEvent(new Event('input', { bubbles: true }));
  if (typeof calculateDue === 'function') calculateDue();
}

function wireAutofill() {
  const paid = $('billAmountPaid');
  if (!paid || paid.dataset.bnAutofill) return;
  paid.dataset.bnAutofill = '1';
  paid.addEventListener('input', (e) => {
    if (e.isTrusted) paid.dataset.bnUserEdited = '1';
  });
  paid.addEventListener('focus', () => { paid.dataset.bnUserEdited = '1'; });

  const badge = document.createElement('button');
  badge.type = 'button';
  badge.id = 'bnPayFull';
  badge.className = 'bn-payfull';
  badge.textContent = 'Paid in full';
  badge.addEventListener('click', () => {
    paid.dataset.bnUserEdited = '';
    paid.value = '';
    autofillPaid();
  });
  const grp = paid.closest('.input-group');
  if (grp) grp.appendChild(badge);
}

/* --------------------------------------------------------------------------
   5.  PRINTER SETUP — one place for A4 / inkjet / colour / Bluetooth

   The settings were spread across three injected sections. A shopkeeper asks
   one question: what comes out when I press print?
   ------------------------------------------------------------------------ */
const PK = 'billnowPrinterSetup';
const pcfg = Object.assign({
  target: 'a4',        // a4 | thermal | pdf
  colour: 'colour',    // colour | mono
  quality: 'normal',   // draft | normal | high
}, JSON.parse(localStorage.getItem(PK) || '{}'));
const psave = () => localStorage.setItem(PK, JSON.stringify(pcfg));

function buildPrinterSetup() {
  const panel = document.querySelector('#settings .settings-panel');
  if (!panel || $('bnPrinterSetup')) return;

  const sec = document.createElement('section');
  sec.id = 'bnPrinterSetup';
  sec.className = 'bn-set-block';
  sec.dataset.group = 'print';
  sec.innerHTML = `
    <h3>Printer setup</h3>
    <p class="bn-note">What comes out when you press print.</p>
    <div class="bn-print-modes" id="bnPrintModes">
      <button type="button" data-t="a4">
        <b>A4 / Letter sheet</b><small>Inkjet, laser or any Wi-Fi printer</small></button>
      <button type="button" data-t="thermal">
        <b>Thermal receipt</b><small>58 / 80 mm Bluetooth roll</small></button>
      <button type="button" data-t="pdf">
        <b>PDF / share</b><small>Save or send on WhatsApp</small></button>
    </div>
    <div class="form-group" id="bnA4Opts">
      <div class="input-group"><label>Colour</label>
        <select id="bnColour">
          <option value="colour">Colour</option>
          <option value="mono">Black &amp; white (saves ink)</option>
        </select></div>
      <div class="input-group"><label>Quality</label>
        <select id="bnQuality">
          <option value="draft">Draft — fastest</option>
          <option value="normal">Normal</option>
          <option value="high">High — for a customer copy</option>
        </select></div>
    </div>
    <div class="bn-note bn-note-warn" id="bnBtNote" hidden>
      A thermal roll printer connects under <b>Bluetooth Printer</b> below.
      An A4 printer does not connect here — it is picked in the Android print
      dialog, which lists every Wi-Fi, Mopria and USB printer on the phone.
    </div>
    <div class="form-group">
      <button type="button" class="btn-success" onclick="bnPrinterSave()">Save printer setup</button>
      <button type="button" class="btn-info" onclick="bnPrinterTest()">Test print</button>
    </div>`;
  panel.insertBefore(sec, panel.firstChild);

  $('bnPrintModes').addEventListener('click', (e) => {
    const b = e.target.closest('[data-t]');
    if (!b) return;
    pcfg.target = b.dataset.t;
    paintPrinterSetup();
  });
  $('bnColour').value = pcfg.colour;
  $('bnQuality').value = pcfg.quality;
  paintPrinterSetup();
}

function paintPrinterSetup() {
  document.querySelectorAll('#bnPrintModes [data-t]').forEach((b) =>
    b.classList.toggle('on', b.dataset.t === pcfg.target));
  const a4 = $('bnA4Opts'), note = $('bnBtNote');
  if (a4) a4.hidden = pcfg.target === 'thermal';
  if (note) note.hidden = pcfg.target !== 'thermal';
  document.body.classList.toggle('print-mono', pcfg.colour === 'mono');
  document.body.classList.toggle('print-compact', pcfg.quality === 'draft');
}

window.bnPrinterSave = function () {
  pcfg.colour = $('bnColour').value;
  pcfg.quality = $('bnQuality').value;
  psave(); paintPrinterSetup();

  // Keep the existing layers in step rather than adding a fourth source of truth.
  if (window.BillNowPrint) {
    window.BillNowPrint.config.target = pcfg.target === 'thermal' ? 'thermal' : 'a4';
    window.BillNowPrint.config.mono = pcfg.colour === 'mono';
    window.BillNowPrint.config.compact = pcfg.quality === 'draft';
    window.BillNowPrint.save();
    window.BillNowPrint.applyBodyClasses();
  }
  if (window.BillNowBT) {
    window.BillNowBT.config.autoPrint = pcfg.target === 'thermal' ? 'always' : 'never';
    window.BillNowBT.saveConfig();
  }
  if (window.bnToast) window.bnToast('Printer setup saved');
};

window.bnPrinterTest = function () {
  if (pcfg.target === 'thermal' && window.bnBtTest) return window.bnBtTest();
  if (window.BillNowSheet) window.BillNowSheet.render();
  window.print();
};

/* --------------------------------------------------------------------------
   6.  RULE 46 FIELDS

   A tax invoice is invalid for the buyer's input credit if a mandatory
   particular is missing, and the penalty falls on the issuer. Two that were
   absent: place of supply (it decides CGST+SGST versus IGST) and the
   reverse-charge declaration.
   ------------------------------------------------------------------------ */
const STATES = {
  '01': 'Jammu & Kashmir', '02': 'Himachal Pradesh', '03': 'Punjab', '04': 'Chandigarh',
  '05': 'Uttarakhand', '06': 'Haryana', '07': 'Delhi', '08': 'Rajasthan', '09': 'Uttar Pradesh',
  '10': 'Bihar', '11': 'Sikkim', '12': 'Arunachal Pradesh', '13': 'Nagaland', '14': 'Manipur',
  '15': 'Mizoram', '16': 'Tripura', '17': 'Meghalaya', '18': 'Assam', '19': 'West Bengal',
  '20': 'Jharkhand', '21': 'Odisha', '22': 'Chhattisgarh', '23': 'Madhya Pradesh',
  '24': 'Gujarat', '27': 'Maharashtra', '29': 'Karnataka', '30': 'Goa', '31': 'Lakshadweep',
  '32': 'Kerala', '33': 'Tamil Nadu', '34': 'Puducherry', '35': 'Andaman & Nicobar',
  '36': 'Telangana', '37': 'Andhra Pradesh', '38': 'Ladakh',
};

/** The first two digits of a GSTIN are the state code. */
function stateOf(gstin) {
  const c = String(gstin || '').trim().slice(0, 2);
  return STATES[c] ? { code: c, name: STATES[c] } : null;
}

/** Same state -> CGST + SGST. Different state -> IGST. Getting this wrong is
 *  the most litigated mistake on Indian invoices. */
function supplyKind() {
  const s = (typeof shopSettings === 'object' && shopSettings) ? shopSettings : {};
  const seller = stateOf(s.gst);
  const buyer = stateOf(($('customerGstin') || {}).value);
  if (!seller) return { kind: 'intra', place: null, note: 'set your GSTIN in Settings' };
  if (!buyer) return { kind: 'intra', place: seller, note: 'unregistered buyer — place of supply is your state' };
  return {
    kind: buyer.code === seller.code ? 'intra' : 'inter',
    place: buyer,
    note: '',
  };
}
window.bnSupplyKind = supplyKind;

function injectRule46() {
  const sheet = $('bnInvoiceSheet');
  if (!sheet || !sheet.firstElementChild) return;
  const sk = supplyKind();

  // Place of supply — fill whatever slot the layout already has, or append one.
  sheet.querySelectorAll('td, div, span').forEach((el) => {
    if (el.children.length) return;
    if (!/place of supply/i.test(el.textContent || '')) return;
    const next = el.nextElementSibling;
    const val = sk.place ? `${sk.place.code} — ${sk.place.name}` : '';
    if (next && !next.textContent.trim()) next.textContent = val;
    else if (!/—/.test(el.textContent)) el.textContent = 'Place of Supply : ' + val;
  });

  if (!sheet.querySelector('.bn-r46')) {
    const bar = document.createElement('div');
    bar.className = 'bn-r46';
    bar.innerHTML = `
      <span>Place of supply: <b>${sk.place ? esc(sk.place.code + ' — ' + sk.place.name) : '—'}</b></span>
      <span>Tax: <b>${sk.kind === 'inter' ? 'IGST (inter-state)' : 'CGST + SGST (intra-state)'}</b></span>
      <span>Reverse charge: <b>No</b></span>`;
    const anchor = sheet.querySelector('.foot, .bottom, .bn-ind-block') || sheet.firstElementChild;
    anchor.insertAdjacentElement('beforebegin', bar);
  }
}

/* --------------------------------------------------------------------------
   BOOT
   ------------------------------------------------------------------------ */
function refresh() {
  isolatePrint();
  dedupeBottomBars();
  addScanButton();
  ensurePayMode();
  wireAutofill();
  autofillPaid();
  buildPrinterSetup();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnProWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw pro]', e.message); }
    return r;
  };
  fn.__bnProWrapped = true;
  window[name] = fn;
}

function boot() {
  refresh();
  ['renderInvoiceTable', 'switchView', 'updateIndustry', 'calculateDue'].forEach((n) => wrap(n, refresh));
  wrap('clearBillingCart', () => {
    const p = $('billAmountPaid');
    if (p) p.dataset.bnUserEdited = '';
    autofillArmed = true;
  });
  ['updatePrintDOM'].forEach((n) => wrap(n, injectRule46));
  window.addEventListener('beforeprint', () => { isolatePrint(); injectRule46(); });
  setTimeout(refresh, 600);
}

window.BillnawPro = { supplyKind, autofillPaid, dedupeBottomBars, printerConfig: pcfg, STATES };

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-checkout  —  Checkout consolidation: who and how, inside the app modal
   ============================================================================ */

/* ============================================================================
   Billnaw — checkout consolidation  v1.0
   Load after billnow-pro.js.

   The app already had a checkout: #checkoutFab -> openCheckout() ->
   #checkoutModal, with items, totals, a UPI QR, an amount-paid field and
   Save & Print. It has been there since the first version.

   I did not see it, and built two more floating bars over it — the
   "RUNNING TOTAL" bar and a "Confirm & print" bar — which is why three
   controls ended up stacked on the billing screen.

   The right correction is to delete mine and finish theirs. This file stands
   the duplicate layer down and adds the one thing the modal was missing: the
   customer and payment step, so the flow reads
       pick items  ->  Checkout  ->  who and how  ->  Save & print.
   ========================================================================== */
(function () {
'use strict';

const $ = (id) => document.getElementById(id);
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
/* app.js writes these figures with .innerText. Reading only .textContent
   returns a stale value wherever the two are not kept in step, which is how a
   prefill silently reads zero. */
const readNum = (el) => {
  if (!el) return 0;
  const t = (el.innerText != null && String(el.innerText).trim() !== '') ? el.innerText : el.textContent;
  return num(t);
};
const inr = (v) => '₹' + num(v).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const hasNativeCheckout = () => !!($('checkoutFab') && typeof window.openCheckout === 'function');

/* --------------------------------------------------------------------------
   1.  STAND DOWN THE DUPLICATES
   ------------------------------------------------------------------------ */
function removeMyBars() {
  ['bnFlowBar', 'bnBillBar', 'bnSteps', 'bnCustPanel', 'bnReviewPanel'].forEach((id) => {
    const el = $(id);
    if (el) el.remove();
  });
  // The flow layer hid the app's own item form while stepping; put it back.
  const billing = $('billing');
  if (billing) Array.from(billing.children).forEach((el) => {
    if (el.style && el.style.display === 'none') el.style.display = '';
  });
  document.documentElement.classList.remove('bn-flow-ready');
  document.documentElement.classList.add('bn-native-checkout');
}

/* --------------------------------------------------------------------------
   2.  CUSTOMER & PAYMENT STEP INSIDE THE EXISTING MODAL

   The modal collected money but never asked who was buying, so the customer
   fields sat at the top of the billing screen where a clerk scrolled past them.
   ------------------------------------------------------------------------ */
const MODES = ['Cash', 'UPI', 'Card', 'Credit'];

function ensurePayMode() {
  if ($('billPaymentMode')) return $('billPaymentMode');
  const el = document.createElement('input');
  el.type = 'hidden';
  el.id = 'billPaymentMode';
  el.value = localStorage.getItem('billnowLastPayMode') || 'Cash';
  document.body.appendChild(el);
  return el;
}

function buildCustomerStep() {
  const body = document.querySelector('#checkoutModal .modal-body');
  if (!body || $('bnCoWho')) return;

  const block = document.createElement('div');
  block.id = 'bnCoWho';
  block.className = 'bn-co-who';
  block.innerHTML = `
    <div class="bn-co-label">Billed to</div>
    <div class="bn-co-grid">
      <input type="text" id="bnCoName" placeholder="Customer name" autocomplete="name">
      <input type="tel" id="bnCoPhone" placeholder="Phone" inputmode="tel">
      <input type="text" id="bnCoGstin" placeholder="GSTIN (for a B2B bill)">
    </div>
    <div id="bnCoRecent" class="bn-co-recent"></div>
    <div class="bn-co-label">Payment</div>
    <div class="bn-co-modes" id="bnCoModes">
      ${MODES.map((m) => `<button type="button" data-pay="${m}">${m}</button>`).join('')}
    </div>
    <div class="bn-co-supply" id="bnCoSupply"></div>`;
  body.insertBefore(block, body.firstChild);

  block.addEventListener('input', mirrorOut);
  block.addEventListener('click', (e) => {
    const m = e.target.closest('[data-pay]');
    if (m) return setMode(m.dataset.pay);
    const r = e.target.closest('[data-cust]');
    if (r) {
      $('bnCoName').value = r.dataset.cust;
      $('bnCoPhone').value = r.dataset.phone || '';
      mirrorOut();
    }
  });
}

/** The billing screen's fields stay the source of truth; this is a nicer face. */
function mirrorOut() {
  [['bnCoName', 'customerName'], ['bnCoPhone', 'customerPhone'], ['bnCoGstin', 'customerGstin']]
    .forEach(([from, to]) => {
      const a = $(from), b = $(to);
      if (a && b && b.value !== a.value) {
        b.value = a.value;
        b.dispatchEvent(new Event('input', { bubbles: true }));
        b.dispatchEvent(new Event('change', { bubbles: true }));
      }
    });
  if (typeof autoFillCustomer === 'function') { try { autoFillCustomer(); } catch (e) {} }
  paintSupply();
}

function mirrorIn() {
  [['customerName', 'bnCoName'], ['customerPhone', 'bnCoPhone'], ['customerGstin', 'bnCoGstin']]
    .forEach(([from, to]) => {
      const a = $(from), b = $(to);
      if (a && b) b.value = a.value || '';
    });
}

function setMode(m) {
  const el = ensurePayMode();
  el.value = m;
  try { localStorage.setItem('billnowLastPayMode', m); } catch (e) {}
  document.querySelectorAll('#bnCoModes [data-pay]').forEach((b) =>
    b.classList.toggle('on', b.dataset.pay === m));

  // Credit means nothing collected yet; everything else means paid in full.
  const paid = $('coPaid');
  if (paid) {
    const grand = readNum($('coGrand'));
    paid.value = m === 'Credit' ? '' : (grand ? grand.toFixed(2) : '');
    if (typeof checkoutPaidChanged === 'function') checkoutPaidChanged();
  }
}

function paintRecent() {
  const host = $('bnCoRecent');
  if (!host) return;
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];
  const seen = new Map();
  for (let i = hist.length - 1; i >= 0 && seen.size < 5; i--) {
    const n = String(hist[i].customer || '').trim();
    if (!n || /^cash customer$/i.test(n) || seen.has(n)) continue;
    seen.set(n, hist[i].phone || '');
  }
  host.innerHTML = [...seen].map(([n, p]) =>
    `<button type="button" data-cust="${esc(n)}" data-phone="${esc(p)}">${esc(n)}</button>`).join('');
}

/** Place of supply decides CGST+SGST versus IGST, and it is the field most
 *  often wrong on Indian invoices. Show the consequence while it can be fixed. */
function paintSupply() {
  const el = $('bnCoSupply');
  if (!el || !window.BillnawPro) return;
  const sk = window.BillnawPro.supplyKind();
  el.innerHTML = `Place of supply <b>${sk.place ? esc(sk.place.code + ' · ' + sk.place.name) : '—'}</b>
    <span>${sk.kind === 'inter' ? 'IGST · inter-state' : 'CGST + SGST · intra-state'}</span>`;
  el.dataset.kind = sk.kind;
}

/* --------------------------------------------------------------------------
   3.  PREFILL THE AMOUNT
   ------------------------------------------------------------------------ */
function prefillPaid() {
  const paid = $('coPaid');
  const grand = $('coGrand');
  if (!paid || !grand) return;
  if (String(paid.value).trim() !== '') return;       // never overwrite
  const mode = (ensurePayMode().value || 'Cash');
  if (/credit/i.test(mode)) return;
  const total = readNum(grand);
  if (total <= 0) return;
  paid.value = total.toFixed(2);
  if (typeof checkoutPaidChanged === 'function') checkoutPaidChanged();
}

/* --------------------------------------------------------------------------
   4.  HOOKS
   ------------------------------------------------------------------------ */
function onOpen() {
  buildCustomerStep();
  mirrorIn();
  paintRecent();
  setMode(ensurePayMode().value || 'Cash');
  prefillPaid();
  paintSupply();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnCoWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw checkout]', e.message); }
    return r;
  };
  fn.__bnCoWrapped = true;
  window[name] = fn;
}

function boot() {
  if (!hasNativeCheckout()) return;   // nothing to consolidate
  removeMyBars();
  wrap('openCheckout', onOpen);
  wrap('renderInvoiceTable', removeMyBars);
  wrap('checkoutPaidChanged', paintSupply);
  setTimeout(removeMyBars, 400);
}

window.BillnawCheckout = { removeMyBars, onOpen, setMode, prefillPaid, hasNativeCheckout };

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-final  —  Scanner preview, thermal logo, export, khata, install
   ============================================================================ */

/* ============================================================================
   Billnaw — final consolidation  v1.0
   Load last, after billnow-checkout.js.

   Six things, each traced to something a shopkeeper hit:

     1. The camera preview never appeared, because #qr-reader lives inside the
        item form the product picker hides with display:none !important. An
        inline style cannot beat !important, so the video element was rendered
        into a hidden box.
     2. The shop logo printed on A4 but never on a thermal receipt.
     3. The sales export had no phone or address, and did not escape commas.
     4. Customer detail worked on a phone and nowhere else.
     5. Desktop had no way to install the app.
     6. The picker showed stock, but not what was already in the cart.
   ========================================================================== */
(function () {
'use strict';

const $ = (id) => document.getElementById(id);
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
const inr = (v) => '₹' + num(v).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const readTxt = (el) => el ? ((el.innerText != null && String(el.innerText).trim() !== '') ? el.innerText : el.textContent) : '';

/* ==========================================================================
   1.  CAMERA PREVIEW
   Move the reader out of the hidden form and put it under the search box,
   which is also where the user is looking when they press Scan.
   ========================================================================== */
function relocateScanner() {
  const reader = $('qr-reader');
  const anchor = $('bnScanBtn') || $('bnPickSearch');
  if (!reader || !anchor || reader.dataset.bnMoved) return;
  reader.dataset.bnMoved = '1';

  const shell = document.createElement('div');
  shell.id = 'bnScanShell';
  shell.className = 'bn-scan-shell no-print';
  shell.hidden = true;
  (anchor.closest('.bn-scan-row') || anchor).insertAdjacentElement('afterend', shell);
  shell.appendChild(reader);

  // A framed viewfinder so the user knows where to hold the barcode.
  const frame = document.createElement('div');
  frame.className = 'bn-scan-frame';
  frame.innerHTML = '<span></span><span></span><span></span><span></span>';
  shell.appendChild(frame);

  const stop = document.createElement('button');
  stop.type = 'button';
  stop.className = 'bn-scan-stop';
  stop.textContent = 'Stop camera';
  stop.addEventListener('click', () => {
    if (typeof stopCameraScanner === 'function') stopCameraScanner();
    hideScanner();
  });
  shell.appendChild(stop);

  // The app toggles reader.style.display; mirror that onto the shell, which is
  // no longer inside anything hidden.
  new MutationObserver(() => {
    const on = reader.style.display && reader.style.display !== 'none';
    shell.hidden = !on;
    if (on) shell.scrollIntoView({ block: 'center' });
  }).observe(reader, { attributes: true, attributeFilter: ['style'] });
}

function hideScanner() {
  const s = $('bnScanShell');
  if (s) s.hidden = true;
  const r = $('qr-reader');
  if (r) r.style.display = 'none';
}

/* ==========================================================================
   2.  LOGO ON A THERMAL RECEIPT
   ESC/POS has no concept of a PNG. The image must be reduced to one bit per
   pixel and shipped as a GS v 0 raster, at a width that is a multiple of 8.
   ========================================================================== */
function logoRaster(dataUrl, cols) {
  return new Promise((resolve) => {
    if (!dataUrl) return resolve(null);
    const img = new Image();
    img.onload = () => {
      try {
        // 32 columns of 12 dots = 384 dots on 58mm; 48 cols = 576 on 80mm.
        const maxDots = cols >= 48 ? 576 : 384;
        const w = Math.floor((maxDots * 0.55) / 8) * 8;      // ~55% of the roll
        const h = Math.max(8, Math.round(w * (img.height / img.width)));
        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        const ctx = c.getContext('2d');
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        const px = ctx.getImageData(0, 0, w, h).data;

        const bytesPerRow = w / 8;
        const out = [];
        for (let y = 0; y < h; y++) {
          for (let b = 0; b < bytesPerRow; b++) {
            let byte = 0;
            for (let bit = 0; bit < 8; bit++) {
              const i = ((y * w) + (b * 8 + bit)) * 4;
              const a = px[i + 3];
              // Luminance, then a hard threshold: a thermal head is on or off.
              const lum = a < 128 ? 255 : (0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2]);
              if (lum < 160) byte |= (0x80 >> bit);
            }
            out.push(byte);
          }
        }
        resolve({ bytes: out, bytesPerRow, height: h, width: w });
      } catch (e) { resolve(null); }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

let logoCache = { src: '', cols: 0, data: null };

async function prepareLogo(cols) {
  const s = (typeof shopSettings === 'object' && shopSettings) ? shopSettings : {};
  const src = s.logoData || '';
  if (!src) { logoCache = { src: '', cols, data: null }; return null; }
  if (logoCache.src === src && logoCache.cols === cols) return logoCache.data;
  const data = await logoRaster(src, cols);
  logoCache = { src, cols, data };
  return data;
}

/** Prepend the logo raster to an ESC/POS stream, centred. */
function withLogo(bytes, logo, cols) {
  if (!logo) return bytes;
  const head = [0x1b, 0x40, 0x1b, 0x61, 0x01];           // init, centre
  const maxBytes = Math.floor((cols >= 48 ? 576 : 384) / 8);
  const pad = Math.max(0, Math.floor((maxBytes - logo.bytesPerRow) / 2));
  const total = logo.bytesPerRow + pad;
  const cmd = [0x1d, 0x76, 0x30, 0x00,
               total & 0xff, (total >> 8) & 0xff,
               logo.height & 0xff, (logo.height >> 8) & 0xff];
  const body = [];
  for (let y = 0; y < logo.height; y++) {
    for (let i = 0; i < pad; i++) body.push(0);
    for (let b = 0; b < logo.bytesPerRow; b++) body.push(logo.bytes[y * logo.bytesPerRow + b]);
  }
  return Uint8Array.from([...head, ...cmd, ...body, 0x0a, ...Array.from(bytes)]);
}

function hookThermalLogo() {
  const bt = window.BillNowBT;
  if (!bt || bt.__bnLogo) return;
  bt.__bnLogo = true;

  const origPrint = bt.printBill;
  bt.printBill = async function (bill, silent) {
    const cols = (bt.config && bt.config.paper === '80') ? 48 : 32;
    await prepareLogo(cols);
    return origPrint.call(this, bill, silent);
  };

  const origBuild = bt.buildReceipt;
  bt.buildReceipt = function (bill, paper) {
    const bytes = origBuild.call(this, bill, paper);
    const cols = paper === 80 || (bt.config && bt.config.paper === '80') ? 48 : 32;
    return withLogo(bytes, logoCache.data, cols);
  };
}

/* ==========================================================================
   3.  EXPORT — phone, address, and commas that do not break the file
   ========================================================================== */
function csvCell(v) {
  let s = String(v ?? '');
  // A leading =, +, - or @ makes a spreadsheet evaluate the cell as a formula.
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

/* Each field is filled from the most recent bill that HAS it. Returning on the
   first bill carrying either field loses the address whenever the latest bill
   was a quick cash sale with only a phone number. */
function customerContact(name) {
  const want = String(name || '').trim();
  const out = { phone: '', address: '', gstin: '' };
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];

  for (let i = hist.length - 1; i >= 0; i--) {
    const b = hist[i];
    if (String(b.customer || '').trim() !== want) continue;
    if (!out.phone && b.phone) out.phone = b.phone;
    if (!out.address && b.address) out.address = b.address;
    if (!out.gstin && (b.gstin || b.customerGstin)) out.gstin = b.gstin || b.customerGstin;
    if (out.phone && out.address && out.gstin) break;
  }

  const led = (typeof customerLedgerData !== 'undefined' && customerLedgerData) ? customerLedgerData : {};
  const rec = led[want];
  if (rec) {
    if (!out.phone && rec.phone) out.phone = rec.phone;
    if (!out.address && rec.address) out.address = rec.address;
    if (!out.gstin && rec.gstin) out.gstin = rec.gstin;
  }
  return out;
}

function hookExport() {
  const orig = window.exportData;
  if (typeof orig !== 'function' || orig.__bnExport) return;

  const fn = function (type) {
    if (type !== 'sales') return orig.apply(this, arguments);
    try {
      const ind = $('industrySelector').value;
      const hist = (typeof billHistoryData !== 'undefined' ? billHistoryData : []).filter((b) => b.industry === ind);
      const head = ['Date', 'Invoice No', 'Customer', 'Phone', 'Address', 'GSTIN',
                    'Items', 'Taxable', 'GST', 'Grand Total', 'Paid', 'Balance', 'Status'];
      const rows = hist.map((b) => {
        const c = customerContact(b.customer);
        const taxable = (b.items || []).reduce((a, l) => a + num(l.taxableValue), 0);
        const gst = (b.items || []).reduce((a, l) => a + num(l.gstAmount), 0);
        const paid = num(b.amountPaid) + num(b.oldGold);
        return [b.date, b.invoiceNo, b.customer, b.phone || c.phone, b.address || c.address,
                b.gstin || c.gstin, b.totalItems, taxable.toFixed(2), gst.toFixed(2),
                b.grandTotal, paid.toFixed(2), (num(b.grandTotal) - paid).toFixed(2), b.status];
      });
      // A BOM makes Excel read it as UTF-8, so the rupee sign and Indian names
      // do not arrive as mojibake.
      const csv = '\uFEFF' + [head, ...rows].map((r) => r.map(csvCell).join(',')).join('\r\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `${ind}_sales_${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(a); a.click();
      setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
      if (window.bnToast) window.bnToast('Exported ' + rows.length + ' bills');
    } catch (e) {
      console.warn('[Billnaw export]', e.message);
      return orig.apply(this, arguments);
    }
  };
  fn.__bnExport = true;
  window.exportData = fn;
}

/* ==========================================================================
   4.  CUSTOMER KHATA — phone on the row, full detail on click, every device
   ========================================================================== */
function enrichKhata() {
  const tb = $('ledgerCustomerBody');
  if (!tb) return;
  Array.from(tb.rows).forEach((tr) => {
    if (tr.dataset.bnKhata) return;
    tr.dataset.bnKhata = '1';
    const cell = tr.cells[0];
    if (!cell) return;
    const name = (readTxt(cell) || '').trim();
    if (!name) return;
    const c = customerContact(name);
    if (c.phone && !/\d{6}/.test(cell.textContent)) {
      const s = document.createElement('span');
      s.className = 'bn-khata-phone';
      s.textContent = c.phone;
      cell.appendChild(s);
    }
    tr.classList.add('bn-khata-row');
    tr.title = 'Tap for full history';
  });
}

/* The mobile sheet exists in billnow-nav.js but only on a phone. On a wide
   screen, show the same content as a centred dialog. */
function openCustomerAnywhere(name) {
  if (window.matchMedia('(max-width: 900px)').matches && window.BillNowNav) {
    return window.BillNowNav.openCustomer(name);
  }
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];
  const bills = hist.filter((b) => String(b.customer || '').trim() === String(name).trim());
  const items = new Map();
  let billed = 0, paid = 0;
  const c = customerContact(name);
  bills.forEach((b) => {
    if (b.isCreditNote || b.reversed) return;
    billed += num(b.grandTotal);
    paid += num(b.amountPaid) + num(b.oldGold);
    (b.items || []).forEach((l) => {
      const k = l.name || 'Item';
      const e = items.get(k) || { qty: 0, amt: 0, last: '' };
      e.qty += num(l.qty) || 1; e.amt += num(l.total); e.last = b.date || e.last;
      items.set(k, e);
    });
  });
  const due = billed - paid;
  const ten = String(c.phone).replace(/\D/g, '').slice(-10);

  let dlg = $('bnCustDlg');
  if (!dlg) {
    dlg = document.createElement('div');
    dlg.id = 'bnCustDlg';
    dlg.className = 'bn-cust-dlg no-print';
    dlg.innerHTML = '<div class="bn-cust-scrim" data-close></div><div class="bn-cust-card"></div>';
    document.body.appendChild(dlg);
    dlg.addEventListener('click', (e) => { if (e.target.hasAttribute('data-close')) dlg.classList.remove('open'); });
  }
  dlg.querySelector('.bn-cust-card').innerHTML = `
    <header><h3>${esc(name)}</h3><button type="button" data-close aria-label="Close">&times;</button></header>
    <div class="bn-cust-kpis">
      <div><span>Phone</span><b>${esc(c.phone || '—')}</b></div>
      <div><span>Bills</span><b>${bills.length}</b></div>
      <div><span>Billed</span><b>${inr(billed)}</b></div>
      <div class="${due > 0.5 ? 'due' : 'ok'}"><span>${due > 0.5 ? 'Outstanding' : 'Settled'}</span><b>${inr(Math.abs(due))}</b></div>
    </div>
    ${c.address ? `<p class="bn-cust-addr">${esc(c.address)}</p>` : ''}
    ${ten.length === 10 ? `<div class="bn-cust-acts">
      <a href="tel:${esc(c.phone)}">Call</a>
      <a href="https://wa.me/91${esc(ten)}" target="_blank" rel="noopener">WhatsApp</a>
    </div>` : ''}
    <div class="bn-cust-sub">Products bought</div>
    ${items.size ? `<table class="bn-cust-table">
      <thead><tr><th>Item</th><th class="n">Qty</th><th class="n">Value</th><th>Last</th></tr></thead>
      <tbody>${[...items.entries()].sort((a, b) => b[1].amt - a[1].amt).map(([k, v]) =>
        `<tr><td>${esc(k)}</td><td class="n">${v.qty}</td><td class="n">${inr(v.amt)}</td><td>${esc(v.last)}</td></tr>`).join('')}</tbody>
    </table>` : '<p class="bn-cust-sub">No purchases recorded.</p>'}
    <div class="bn-cust-sub">Invoices</div>
    <table class="bn-cust-table">
      <tbody>${bills.slice().reverse().slice(0, 20).map((b) =>
        `<tr><td>${esc(b.invoiceNo)}</td><td>${esc(b.date)}</td>
             <td class="n">${inr(b.grandTotal)}</td><td>${esc(b.status || '')}</td></tr>`).join('')}</tbody>
    </table>`;
  dlg.classList.add('open');
}
window.bnOpenCustomer = openCustomerAnywhere;

function wireKhataClicks() {
  if (document.body.dataset.bnKhataWired) return;
  document.body.dataset.bnKhataWired = '1';
  document.body.addEventListener('click', (e) => {
    const tr = e.target.closest('#ledgerCustomerBody tr');
    if (!tr || e.target.closest('button, a, input')) return;
    const name = (readTxt(tr.cells[0]) || '').replace(/\d{6,}/g, '').trim();
    if (name) openCustomerAnywhere(name);
  });
}

/* ==========================================================================
   5.  INSTALL — desktop and Android both need a visible affordance
   ========================================================================== */
let deferredPrompt = null;

function wireInstall() {
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    showInstall();
  });
  window.addEventListener('appinstalled', () => {
    deferredPrompt = null;
    const b = $('bnInstall');
    if (b) b.remove();
  });
  // Already running as an installed app: nothing to offer.
  if (window.matchMedia('(display-mode: standalone)').matches) return;
}

function showInstall() {
  if ($('bnInstall') || !deferredPrompt) return;
  const b = document.createElement('button');
  b.id = 'bnInstall';
  b.type = 'button';
  b.className = 'bn-install no-print';
  b.innerHTML = '<span aria-hidden="true">⤓</span> Install Billnaw';
  b.addEventListener('click', async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    try { await deferredPrompt.userChoice; } catch (e) {}
    deferredPrompt = null;
    b.remove();
  });
  document.body.appendChild(b);
}

/* ==========================================================================
   6.  EXACT STOCK IN THE PICKER — on the shelf, minus what is already billed
   ========================================================================== */
function paintExactStock() {
  const list = $('bnPickList');
  if (!list) return;
  const cart = new Map();
  (typeof currentInvoice !== 'undefined' ? currentInvoice : []).forEach((l) => {
    cart.set(l.name, (cart.get(l.name) || 0) + (num(l.qty) || 0));
  });
  list.querySelectorAll('.bn-pick').forEach((el) => {
    const name = el.dataset.pick;
    const inCart = cart.get(name) || 0;
    const qt = el.querySelector('.qt');
    if (!qt || !qt.dataset.bnShelf) {
      if (qt) qt.dataset.bnShelf = String(num(qt.textContent));
    }
    const shelf = num(qt && qt.dataset.bnShelf);
    const left = shelf - inCart;
    if (!qt) return;
    qt.innerHTML = `${left}<small>${inCart ? inCart + ' in bill' : (left <= 0 ? 'out' : 'left')}</small>`;
    el.dataset.state = left <= 0 ? 'out' : left <= 5 ? 'low' : 'ok';
  });
}

/* ==========================================================================
   BOOT
   ========================================================================== */
function refresh() {
  relocateScanner();
  hookThermalLogo();
  hookExport();
  enrichKhata();
  wireKhataClicks();
  paintExactStock();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnFinalWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw final]', e.message); }
    return r;
  };
  fn.__bnFinalWrapped = true;
  window[name] = fn;
}

function boot() {
  wireInstall();
  refresh();
  ['switchView', 'renderCustomerLedger', 'renderInvoiceTable', 'updateIndustry', 'loadSettings']
    .forEach((n) => wrap(n, refresh));
  wrap('stopCameraScanner', hideScanner);
  setTimeout(refresh, 600);
}

window.BillnawFinal = {
  logoRaster, withLogo, prepareLogo, csvCell, customerContact,
  openCustomer: openCustomerAnywhere, paintExactStock, relocateScanner,
};

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-ops  —  Sales filter, serial entry, edit safety, diagnostics
   ============================================================================ */

/* ============================================================================
   Billnaw — operations  v1.0
   Load after billnow-final.js.

   Five reported faults, each traced to a specific line:

   1. "Today" filtered the KPI strip but not the bill list. renderSales()
      computed a date range and never applied it to the rows below.
   2. There is no serial/IMEI field in the stock form — only invName, invBatch,
      invHsn, invGst, invCost, invPrice, invQty, invExpiry, invPurity, invMaking.
      Serials were being typed into Batch/SKU as one comma-separated blob.
   3. Call/WhatsApp broke on any phone that was not exactly ten digits after
      stripping, because the link was built from a blind slice(-10).
   4. editHistoricalBill() does billHistoryData.splice(index, 1) immediately.
      Abandon the edit and the invoice is gone, with no undo.
   5. Nothing told a shopkeeper whether the app was actually installed and
      offline-ready, or whether an update was waiting.
   ========================================================================== */
(function () {
'use strict';

const $ = (id) => document.getElementById(id);
const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[₹,\s]/g, '')); return Number.isFinite(n) ? n : 0; };
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const readTxt = (el) => el ? ((el.innerText != null && String(el.innerText).trim() !== '') ? el.innerText : el.textContent) : '';

/* ==========================================================================
   1.  SALES RANGE MUST FILTER THE LIST, NOT JUST THE HEADLINE
   ========================================================================== */
function billTime(b) {
  const t = Date.parse(b.timestamp || '');
  if (Number.isFinite(t)) return t;
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(String(b.date || ''));
  return m ? new Date(+m[3], +m[2] - 1, +m[1]).getTime() : 0;
}

/** Match a rendered row back to its record.
 *
 *  Reading the invoice number out of the row text does not work: the cells run
 *  together as "16/7/2025INV-3C", so \b never fires between "5" and "INV", and
 *  a greedy character class then swallows the customer initial too.
 *
 *  Every row already carries its own index inside the action buttons
 *  (reprintHistoricalBill(0), editHistoricalBill(1) ...). That is exact. */
function recordOf(el) {
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];
  const btn = el.querySelector && el.querySelector('[onclick*="HistoricalBill("]');
  if (btn) {
    const m = /HistoricalBill\((\d+)\)/.exec(btn.getAttribute('onclick') || '');
    if (m) return hist[Number(m[1])] || null;
  }
  // Fallback for a card that has lost its buttons: anchored number match.
  const t = readTxt(el) || '';
  const m2 = t.match(/(?:INV|CN)-\d+(?:-CN)?/);
  return m2 ? hist.find((b) => b.invoiceNo === m2[0]) || null : null;
}

function filterSalesList() {
  const panel = $('bnSalesPanel');
  if (!panel || !window.BillNowNav) return;
  const chip = panel.querySelector('[data-range].on');
  const kind = chip ? chip.dataset.range : 'month';
  const [from, to] = window.BillNowNav.rangeBounds(kind, $('bnFrom'), $('bnTo'));

  const apply = (el) => {
    const rec = recordOf(el);
    // A row we cannot identify stays visible: hiding data by accident is worse
    // than showing one row too many.
    let keep = true;
    if (rec) { const t = billTime(rec); keep = t >= from && t <= to; }
    el.style.display = keep ? '' : 'none';
  };

  const body = $('historyBody');
  if (body) Array.from(body.rows).forEach(apply);
  const cards = $('bnHistList');
  if (cards) Array.from(cards.children).forEach(apply);

  // Count the records, not the elements: the table and the mobile card list
  // both render the same bills, so counting the DOM doubles every figure.
  const hist = (typeof billHistoryData !== 'undefined' && billHistoryData) ? billHistoryData : [];
  const shown = hist.filter((b) => { const t = billTime(b); return t >= from && t <= to; }).length;
  const hidden = hist.length - shown;

  let note = $('bnRangeNote');
  if (!note) {
    note = document.createElement('div');
    note.id = 'bnRangeNote';
    note.className = 'bn-range-note no-print';
    (cards || body || panel).insertAdjacentElement('beforebegin', note);
  }
  note.textContent = hidden
    ? `Showing ${shown} bill${shown === 1 ? '' : 's'} in this period · ${hidden} outside`
    : `Showing all ${shown} bill${shown === 1 ? '' : 's'}`;
  note.hidden = shown === 0 && hidden === 0;

  if (shown === 0) {
    let empty = $('bnRangeEmpty');
    if (!empty) {
      empty = document.createElement('div');
      empty.id = 'bnRangeEmpty';
      empty.className = 'bn-empty no-print';
      note.insertAdjacentElement('afterend', empty);
    }
    empty.textContent = 'No bills in this period.';
    empty.hidden = false;
  } else if ($('bnRangeEmpty')) {
    $('bnRangeEmpty').hidden = true;
  }
}

/* ==========================================================================
   2.  SERIAL / IMEI AT STOCK ENTRY
   Electronics is sold by identity, not by count. Recording serials only at
   billing time means a phone can be received without ever being registered.
   ========================================================================== */
function buildSerialField() {
  const qty = $('invQty');
  if (!qty || $('invSerials')) return;
  const grp = qty.closest('.form-group') || qty.parentElement;

  const wrap = document.createElement('div');
  wrap.className = 'form-group industry-field elec-only bn-serial-group';
  wrap.innerHTML = `
    <div class="input-group" style="flex:2;">
      <label for="invSerials">Serial / IMEI numbers <span class="bn-hint">one per line, or comma separated</span></label>
      <textarea id="invSerials" rows="3" placeholder="358123456789012&#10;358123456789013"></textarea>
      <div class="bn-serial-count" id="invSerialCount"></div>
    </div>`;
  grp.insertAdjacentElement('afterend', wrap);

  const ta = $('invSerials');
  ta.addEventListener('input', () => {
    const list = parseSerials(ta.value);
    const c = $('invSerialCount');
    const q = num(qty.value);
    if (!list.length) { c.textContent = ''; c.dataset.state = ''; return; }
    const dupes = list.length - new Set(list).size;
    // A serial count that disagrees with the quantity is a stock error waiting
    // to happen, so say so before it is saved.
    c.textContent = `${list.length} serial${list.length === 1 ? '' : 's'}`
      + (dupes ? ` · ${dupes} duplicate${dupes === 1 ? '' : 's'}` : '')
      + (q && list.length !== q ? ` · quantity is ${q}` : '');
    c.dataset.state = (dupes || (q && list.length !== q)) ? 'warn' : 'ok';
    if (!dupes && list.length && String(qty.value) !== String(list.length)) {
      qty.value = list.length;                        // the count follows the list
      qty.dispatchEvent(new Event('input', { bubbles: true }));
    }
  });
}

function parseSerials(v) {
  return String(v || '').split(/[\n,;]+/).map((s) => s.trim()).filter(Boolean);
}

function hookInventorySave() {
  const orig = window.saveInventoryItem || window.addInventoryItem || window.quickAddItem;
  const name = window.saveInventoryItem ? 'saveInventoryItem'
             : window.addInventoryItem ? 'addInventoryItem'
             : window.quickAddItem ? 'quickAddItem' : null;
  if (!name || orig.__bnSerial) return;

  const fn = function () {
    const ta = $('invSerials');
    const list = ta ? parseSerials(ta.value) : [];
    const target = ($('invName') || {}).value;
    const r = orig.apply(this, arguments);
    try {
      if (list.length && target) {
        const ind = $('industrySelector').value;
        const inv = (typeof isolatedInventory !== 'undefined' ? isolatedInventory : window.isolatedInventory)[ind] || [];
        const it = inv.find((i) => i.name === target);
        if (it) {
          // Merge rather than replace: a second inward of the same model adds
          // units, it does not discard the ones already on the shelf.
          const merged = Array.from(new Set([...(it.serials || []), ...list]));
          it.serials = merged;
          if (!it.batch) it.batch = merged[0];
          localStorage.setItem('myBusinessInventory', JSON.stringify(
            typeof isolatedInventory !== 'undefined' ? isolatedInventory : window.isolatedInventory));
        }
      }
      if (ta) { ta.value = ''; const c = $('invSerialCount'); if (c) c.textContent = ''; }
    } catch (e) { console.warn('[Billnaw serials]', e.message); }
    return r;
  };
  fn.__bnSerial = true;
  window[name] = fn;
}

/** When a serial-bearing item is picked for a bill, offer the ones in stock. */
function serialsInStock(itemName) {
  try {
    const ind = $('industrySelector').value;
    const inv = (typeof isolatedInventory !== 'undefined' ? isolatedInventory : window.isolatedInventory)[ind] || [];
    const it = inv.find((i) => i.name === itemName);
    const all = (it && it.serials) || [];
    const sold = new Set();
    (typeof billHistoryData !== 'undefined' ? billHistoryData : []).forEach((b) => {
      if (b.isCreditNote || b.reversed) return;
      (b.items || []).forEach((l) => String(l.dyn1 || '').split(',').forEach((s) => {
        s = s.trim(); if (s) sold.add(s);
      }));
    });
    return all.filter((s) => !sold.has(s));
  } catch (e) { return []; }
}
window.bnSerialsInStock = serialsInStock;

/* ==========================================================================
   3.  PHONE NUMBERS THAT ARE NOT EXACTLY TEN DIGITS
   ========================================================================== */
function normalisePhone(raw) {
  const d = String(raw || '').replace(/\D/g, '');
  if (!d) return null;
  // 91XXXXXXXXXX, 091XXXXXXXXXX, 0XXXXXXXXXX and XXXXXXXXXX all mean the same
  // ten-digit subscriber number.
  let ten = d;
  if (ten.length > 10 && ten.startsWith('91')) ten = ten.slice(2);
  if (ten.length === 11 && ten.startsWith('0')) ten = ten.slice(1);
  if (ten.length !== 10) return null;
  return { ten, e164: '91' + ten, display: '+91 ' + ten.replace(/(\d{5})(\d{5})/, '$1 $2') };
}
window.bnPhone = normalisePhone;

/** Repair any Call/WhatsApp link already rendered with a bad number. */
function fixContactLinks(root) {
  (root || document).querySelectorAll('a[href^="tel:"], a[href*="wa.me"]').forEach((a) => {
    const raw = a.getAttribute('href').replace(/^tel:|^https?:\/\/wa\.me\//, '');
    const p = normalisePhone(raw);
    if (!p) { a.setAttribute('aria-disabled', 'true'); a.classList.add('bn-link-off'); a.removeAttribute('href'); return; }
    a.classList.remove('bn-link-off');
    a.removeAttribute('aria-disabled');
    a.href = a.textContent.trim().toLowerCase().startsWith('call')
      ? 'tel:+' + p.e164
      : 'https://wa.me/' + p.e164;
  });
}

/* ==========================================================================
   4.  EDITING A BILL MUST BE REVERSIBLE
   editHistoricalBill() splices the record out of history straight away. Walk
   away and the invoice is gone. Keep a snapshot and show a way back.
   ========================================================================== */
const EDIT_KEY = 'billnawPendingEdit';

function hookEdit() {
  const orig = window.editHistoricalBill;
  if (typeof orig !== 'function' || orig.__bnEdit) return;

  const fn = function (index) {
    const bill = (typeof billHistoryData !== 'undefined' ? billHistoryData : [])[index];
    if (bill) {
      try { localStorage.setItem(EDIT_KEY, JSON.stringify({ bill, at: Date.now() })); }
      catch (e) { console.warn('[Billnaw edit] snapshot failed:', e.message); }
    }
    const r = orig.apply(this, arguments);
    paintEditBanner();
    if (window.BillnawPicker) window.BillnawPicker.refresh();
    if (window.BillnawFinal) window.BillnawFinal.paintExactStock();
    return r;
  };
  fn.__bnEdit = true;
  window.editHistoricalBill = fn;

  // A saved bill completes the edit; a cleared cart abandons it.
  const fin = window.finalizeAndPrintInvoice;
  if (typeof fin === 'function' && !fin.__bnEdit) {
    const f2 = function () {
      const r = fin.apply(this, arguments);
      try { localStorage.removeItem(EDIT_KEY); } catch (e) {}
      paintEditBanner();
      return r;
    };
    f2.__bnEdit = true;
    window.finalizeAndPrintInvoice = f2;
  }
}

function pendingEdit() {
  try { return JSON.parse(localStorage.getItem(EDIT_KEY) || 'null'); } catch (e) { return null; }
}

function paintEditBanner() {
  const pend = pendingEdit();
  let bar = $('bnEditBar');
  if (!pend) { if (bar) bar.remove(); return; }
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'bnEditBar';
    bar.className = 'bn-editbar no-print';
    const billing = $('billing');
    if (!billing) return;
    (billing.querySelector('.header-top') || billing.firstElementChild)
      .insertAdjacentElement('afterend', bar);
  }
  bar.innerHTML = `
    <span>Editing <b>${esc(pend.bill.invoiceNo)}</b> — the original is held until you save.</span>
    <button type="button" id="bnEditCancel">Cancel edit</button>`;
  $('bnEditCancel').onclick = cancelEdit;
}

function cancelEdit() {
  const pend = pendingEdit();
  if (!pend) return;
  if (!confirm(`Restore ${pend.bill.invoiceNo} and discard the changes?`)) return;
  try {
    const hist = typeof billHistoryData !== 'undefined' ? billHistoryData : window.billHistoryData;
    // Put the record back where it belongs, and undo the stock and ledger
    // movements the edit performed on the way in.
    if (!hist.some((b) => b.invoiceNo === pend.bill.invoiceNo)) {
      hist.push(pend.bill);
      hist.sort((a, b) => billTime(a) - billTime(b));

      const ind = pend.bill.industry || $('industrySelector').value;
      const inv = (typeof isolatedInventory !== 'undefined' ? isolatedInventory : window.isolatedInventory);
      (pend.bill.items || []).forEach((l) => {
        const it = (inv[ind] || []).find((i) => i.name === l.name);
        if (it) it.qty = num(it.qty) - num(l.qty);
      });

      const cust = pend.bill.customer;
      if (cust && cust !== 'Cash Customer' && typeof customerLedgerData !== 'undefined' && customerLedgerData[cust]) {
        customerLedgerData[cust].billed += num(pend.bill.grandTotal);
        customerLedgerData[cust].paid += num(pend.bill.amountPaid) + num(pend.bill.oldGold);
      }

      localStorage.setItem('myBusinessBillHistory', JSON.stringify(hist));
      localStorage.setItem('myBusinessInventory', JSON.stringify(inv));
      if (typeof customerLedgerData !== 'undefined')
        localStorage.setItem('myBusinessLedger', JSON.stringify(customerLedgerData));
    }
    localStorage.removeItem(EDIT_KEY);
    if (typeof clearBillingCart === 'function') clearBillingCart(true);
    ['renderBillHistory', 'renderInventoryTable', 'renderCustomerLedger', 'renderStockStatement',
     'renderInvoiceTable', 'runAlertsEngine'].forEach((n) => { if (typeof window[n] === 'function') window[n](); });
    paintEditBanner();
    if (window.bnToast) window.bnToast(pend.bill.invoiceNo + ' restored');
  } catch (e) { alert('Could not restore the bill: ' + e.message); }
}

/* ==========================================================================
   5.  IS THIS ACTUALLY INSTALLED AND OFFLINE-READY?
   A support call should start with a fact, not a guess.
   ========================================================================== */
async function diagnose() {
  const d = {
    installed: window.matchMedia('(display-mode: standalone)').matches ||
               window.navigator.standalone === true,
    secure: window.isSecureContext,
    online: navigator.onLine,
    serviceWorker: 'unsupported',
    cached: 0,
    manifest: 'unknown',
    version: 'unknown',
    storage: 'unknown',
  };
  if (navigator.serviceWorker && typeof navigator.serviceWorker.getRegistration === 'function') {
    const reg = await navigator.serviceWorker.getRegistration();
    d.serviceWorker = reg ? (reg.active ? 'active' : 'installing') : 'not registered';
    d.updateWaiting = !!(reg && reg.waiting);
  }
  if (window.caches) {
    const keys = await caches.keys();
    d.version = keys.find((k) => k.startsWith('billnow-erp')) || 'none';
    for (const k of keys) d.cached += (await (await caches.open(k)).keys()).length;
  }
  try {
    const r = await fetch('manifest.json', { cache: 'no-store' });
    d.manifest = r.ok ? 'reachable' : 'HTTP ' + r.status;
  } catch (e) { d.manifest = d.online ? 'unreachable' : 'offline (cached copy in use)'; }
  if (navigator.storage && navigator.storage.persisted) {
    d.storage = (await navigator.storage.persisted()) ? 'protected' : 'not protected';
  }
  return d;
}
window.bnDiagnose = diagnose;

function buildDiagnostics() {
  const panel = document.querySelector('#settings .settings-panel');
  if (!panel || $('bnDiag')) return;
  const sec = document.createElement('section');
  sec.id = 'bnDiag';
  sec.className = 'bn-set-block';
  sec.dataset.group = 'data';
  sec.innerHTML = `
    <h3>App health</h3>
    <p class="bn-note">Read this out if you ever need support.</p>
    <div class="bn-diag" id="bnDiagOut">Checking…</div>
    <div class="form-group">
      <button type="button" class="btn-info" onclick="bnRefreshDiag()">Re-check</button>
      <button type="button" class="btn-warning" onclick="bnForceUpdate()">Force update</button>
    </div>`;
  panel.appendChild(sec);
  paintDiagnostics();
}

async function paintDiagnostics() {
  const out = $('bnDiagOut');
  if (!out) return;
  const d = await diagnose();
  const row = (label, value, good) =>
    `<div><span>${esc(label)}</span><b data-ok="${good ? '1' : '0'}">${esc(value)}</b></div>`;
  out.innerHTML =
    row('Installed as an app', d.installed ? 'Yes' : 'No — running in the browser', d.installed) +
    row('Secure connection', d.secure ? 'Yes (https)' : 'No — camera and Bluetooth will not work', d.secure) +
    row('Offline engine', d.serviceWorker, d.serviceWorker === 'active') +
    row('Files cached', String(d.cached), d.cached > 10) +
    row('Cache version', d.version, d.version !== 'none') +
    row('Manifest', d.manifest, /reachable|cached/.test(d.manifest)) +
    row('Data protection', d.storage, d.storage === 'protected') +
    row('Connection', d.online ? 'Online' : 'Offline — billing still works', true);
}
window.bnRefreshDiag = paintDiagnostics;

window.bnForceUpdate = async function () {
  if (!('serviceWorker' in navigator)) return alert('Not supported in this browser.');
  const reg = await navigator.serviceWorker.getRegistration();
  if (!reg) return alert('The offline engine is not registered yet. Reload once while online.');
  await reg.update();
  if (reg.waiting) reg.waiting.postMessage('SKIP_WAITING');
  alert('Checked for an update. The app will reload if a new version was found.');
};

/* An update that never activates is the reason a fix "did not appear". */
function wireUpdateNotice() {
  const sw = navigator.serviceWorker;
  if (!sw || typeof sw.getRegistration !== 'function') return;
  sw.getRegistration().then((reg) => {
    if (!reg) return;
    const offer = (worker) => {
      if (!worker || $('bnUpdateBar')) return;
      const bar = document.createElement('div');
      bar.id = 'bnUpdateBar';
      bar.className = 'bn-updatebar no-print';
      bar.innerHTML = '<span>A new version of Billnaw is ready.</span><button type="button">Update now</button>';
      bar.querySelector('button').onclick = () => {
        worker.postMessage('SKIP_WAITING');
        bar.querySelector('button').textContent = 'Updating…';
      };
      document.body.appendChild(bar);
    };
    if (reg.waiting) offer(reg.waiting);
    reg.addEventListener('updatefound', () => {
      const w = reg.installing;
      if (w) w.addEventListener('statechange', () => { if (w.state === 'installed' && reg.active) offer(w); });
    });
  }).catch(() => {});

  let reloaded = false;
  if (typeof sw.addEventListener === 'function') {
    sw.addEventListener('controllerchange', () => {
      if (reloaded) return; reloaded = true; location.reload();
    });
  }
}

/* ==========================================================================
   BOOT
   ========================================================================== */
function refresh() {
  buildSerialField();
  hookInventorySave();
  hookEdit();
  paintEditBanner();
  buildDiagnostics();
  filterSalesList();
  fixContactLinks();
}

function wrap(name, after) {
  const orig = window[name];
  if (typeof orig !== 'function' || orig.__bnOpsWrapped) return;
  const fn = function () {
    const r = orig.apply(this, arguments);
    try { after(); } catch (e) { console.warn('[Billnaw ops]', e.message); }
    return r;
  };
  fn.__bnOpsWrapped = true;
  window[name] = fn;
}

function boot() {
  refresh();
  wireUpdateNotice();
  ['switchView', 'updateIndustry', 'renderBillHistory', 'renderCustomerLedger',
   'renderInventoryTable', 'clearBillingCart'].forEach((n) => wrap(n, refresh));

  // The sales panel repaints on its own; re-apply the row filter after it.
  const panel = () => $('bnSalesPanel');
  document.addEventListener('click', (e) => {
    if (e.target.closest('#bnSalesPanel [data-range], #bnSalesPanel [data-mode]')) setTimeout(filterSalesList, 30);
  });
  document.addEventListener('change', (e) => {
    if (e.target.closest('#bnSalesPanel')) setTimeout(filterSalesList, 30);
  });
  new MutationObserver(() => fixContactLinks()).observe(document.body, { childList: true, subtree: true });
  setTimeout(refresh, 700);
}

window.BillnawOps = {
  filterSalesList, parseSerials, serialsInStock, normalisePhone,
  diagnose, cancelEdit, pendingEdit, billTime,
};

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();


/* ============================================================================
   billnow-native  —  Capacitor bridge (inert in a browser)
   ============================================================================ */

/* ============================================================================
   BillNow — Android (Capacitor) native layer  v1.0
   Load LAST:  app.js -> billnow-addon.js -> billnow-native.js
   No bundler required: uses window.Capacitor.Plugins at runtime.
   In a plain browser this file does nothing and the PWA behaves as before.
   ========================================================================== */
(function () {
'use strict';

const Cap = window.Capacitor;
const isNative = !!(Cap && Cap.isNativePlatform && Cap.isNativePlatform());
if (!isNative) return;                       // browser: leave Web Bluetooth path alone

const P = Cap.Plugins || {};
const Ble = P.BluetoothLe;
const App = P.App;
const KeepAwake = P.KeepAwake;
const Toast = P.Toast;

document.documentElement.classList.add('bn-native');

/* --------------------------------------------------------------------------
   1.  NATIVE BLE PRINTER TRANSPORT
       The community plugin's raw API takes hex strings, so we convert.
       Advantage over Web Bluetooth: no Chrome chooser dialog, the device is
       remembered by MAC across app restarts, and scanning is under our control.
   ------------------------------------------------------------------------ */
const PRINTER_SERVICES = [
  '000018f0-0000-1000-8000-00805f9b34fb',
  '0000ff00-0000-1000-8000-00805f9b34fb',
  '0000ffe0-0000-1000-8000-00805f9b34fb',
  '0000ae30-0000-1000-8000-00805f9b34fb',
  '49535343-fe7d-4ae5-8fa9-9fafd205e455',
  'e7810a71-73ae-499d-8c15-faa9aef0c3f2',
  '0000fee7-0000-1000-8000-00805f9b34fb'
];
const WRITE_CHARS = {
  '000018f0-0000-1000-8000-00805f9b34fb': '00002af1-0000-1000-8000-00805f9b34fb',
  '0000ff00-0000-1000-8000-00805f9b34fb': '0000ff02-0000-1000-8000-00805f9b34fb',
  '0000ffe0-0000-1000-8000-00805f9b34fb': '0000ffe1-0000-1000-8000-00805f9b34fb',
  '0000ae30-0000-1000-8000-00805f9b34fb': '0000ae01-0000-1000-8000-00805f9b34fb',
  '49535343-fe7d-4ae5-8fa9-9fafd205e455': '49535343-8841-43f4-a8d4-ecbe34729bb3',
  'e7810a71-73ae-499d-8c15-faa9aef0c3f2': 'bef8d6c9-9c21-4c9e-b632-bd58c1009f9f',
  '0000fee7-0000-1000-8000-00805f9b34fb': '000036f5-0000-1000-8000-00805f9b34fb'
};

const SAVED = 'billnowPrinterDevice';
const state = { deviceId: '', name: '', service: '', chr: '', connected: false, ready: false };
const hex = b => Array.from(b).map(x => x.toString(16).padStart(2, '0')).join(' ');
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function ensureInit() {
  if (state.ready) return;
  await Ble.initialize({ androidNeverForLocation: true });
  state.ready = true;
}

/** Probe each known service until one accepts a zero-length ESC/POS init. */
async function resolveChannel(deviceId) {
  for (const svc of PRINTER_SERVICES) {
    const chr = WRITE_CHARS[svc];
    try {
      await Ble.writeWithoutResponse({ deviceId, service: svc, characteristic: chr, value: '1b 40' });
      return { service: svc, chr };
    } catch (e) { /* wrong service, keep probing */ }
  }
  return null;
}

async function nativeConnect(silent) {
  try {
    await ensureInit();
    const saved = JSON.parse(localStorage.getItem(SAVED) || 'null');

    let deviceId = saved && saved.deviceId;
    let name = saved && saved.name;

    if (!deviceId || !state.connected) {
      // requestDevice shows the OS-level picker filtered to likely printers
      const res = await Ble.requestDevice({ services: [], optionalServices: PRINTER_SERVICES, allowDuplicates: false });
      if (res && res.deviceId) { deviceId = res.deviceId; name = res.name || 'Printer'; }
    }
    if (!deviceId) return false;

    await Ble.connect({ deviceId, timeout: 12000 });
    const ch = await resolveChannel(deviceId);
    if (!ch) {
      alert('Connected to "' + (name || 'device') + '" but no ESC/POS channel responded.\n\n' +
            'If this is a Bluetooth Classic (SPP) printer, install the SPP plugin — see BUILD_ANDROID.md.');
      try { await Ble.disconnect({ deviceId }); } catch (e) {}
      return false;
    }
    Object.assign(state, { deviceId, name, service: ch.service, chr: ch.chr, connected: true });
    localStorage.setItem(SAVED, JSON.stringify({ deviceId, name }));
    return true;
  } catch (e) {
    if (!silent) alert('Printer connect failed: ' + (e.message || e));
    return false;
  }
}

async function nativeWrite(bytes) {
  if (!state.connected) throw new Error('Printer not connected');
  const CHUNK = 200;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    const slice = bytes.slice(i, i + CHUNK);
    await Ble.writeWithoutResponse({
      deviceId: state.deviceId, service: state.service,
      characteristic: state.chr, value: hex(slice)
    });
    await sleep(12);
  }
}

if (Ble && window.BillNowBT) {
  window.BillNowBT.setTransport({
    connect: nativeConnect,
    disconnect: async () => {
      try { if (state.deviceId) await Ble.disconnect({ deviceId: state.deviceId }); } catch (e) {}
      state.connected = false;
    },
    write: nativeWrite,
    isConnected: () => state.connected,
    deviceName: () => state.name
  });

  // silent reconnect on cold start so the first bill of the day just prints
  setTimeout(() => {
    if (localStorage.getItem(SAVED)) nativeConnect(true).then(() => window.BillNowBT.repaint());
  }, 1500);
}

/* --------------------------------------------------------------------------
   2.  ANDROID BEHAVIOUR
   ------------------------------------------------------------------------ */

// Hardware back button: close modal -> go to dashboard -> confirm exit.
// Without this, back exits the app mid-bill and the counter loses the cart.
if (App) {
  App.addListener('backButton', () => {
    const modal = document.querySelector('.modal-backdrop[style*="flex"], .modal.show, #checkoutModal[style*="flex"]');
    if (modal && typeof closeCheckout === 'function') { closeCheckout(); return; }
    const active = document.querySelector('.view-section:not([style*="none"])');
    if (active && active.id !== 'dashboard') { switchView('dashboard'); syncBottomNav('dashboard'); return; }
    if (typeof currentInvoice !== 'undefined' && currentInvoice.length) {
      if (!confirm('A bill is still open. Exit anyway?')) return;
    }
    App.exitApp();
  });

  // Flush to disk whenever the app is backgrounded — Android can kill it silently
  App.addListener('appStateChange', ({ isActive }) => {
    if (!isActive) {
      try {
        localStorage.setItem('myBusinessInventory', JSON.stringify(isolatedInventory));
        localStorage.setItem('myBusinessBillHistory', JSON.stringify(billHistoryData));
      } catch (e) {}
      if (KeepAwake) KeepAwake.allowSleep().catch(() => {});
    } else if (KeepAwake) {
      KeepAwake.keepAwake().catch(() => {});
    }
  });
}

// Screen stays on while the billing screen is open
if (KeepAwake) KeepAwake.keepAwake().catch(() => {});

/* --------------------------------------------------------------------------
   3.  PERFORMANCE GUARD
       The render functions rebuild every table row on every keystroke.
       On a ₹8,000 Android phone with 1,500+ SKUs that is visible lag.
       We cap rendered rows and let search reach the rest.
   ------------------------------------------------------------------------ */
const ROW_CAP = 150;
function capTable(tbodyId, noticeText) {
  const tb = document.getElementById(tbodyId);
  if (!tb) return;
  const rows = tb.children;
  if (rows.length <= ROW_CAP) return;
  for (let i = ROW_CAP; i < rows.length; i++) rows[i].style.display = 'none';
  if (!document.getElementById(tbodyId + 'Cap')) {
    const tr = document.createElement('tr');
    tr.id = tbodyId + 'Cap';
    tr.innerHTML = '<td colspan="20" style="text-align:center;padding:14px;color:#64748b;font-size:.85em;">' +
      noticeText + '</td>';
    tb.appendChild(tr);
  }
}
['renderInventoryTable', 'renderBillHistory', 'renderStockStatement'].forEach(fn => {
  const orig = window[fn];
  if (typeof orig !== 'function') return;
  window[fn] = function () {
    const r = orig.apply(this, arguments);
    const map = { renderInventoryTable: 'inventoryBody', renderBillHistory: 'billHistoryBody', renderStockStatement: 'stockStatementBody' };
    capTable(map[fn], 'Showing first ' + ROW_CAP + ' rows — use search to find the rest.');
    return r;
  };
});

// Debounce the inventory search so typing doesn't re-filter on every keypress
if (typeof window.filterInventory === 'function') {
  const orig = window.filterInventory;
  let t;
  window.filterInventory = function () { clearTimeout(t); t = setTimeout(() => orig.apply(this, arguments), 140); };
}

/* --------------------------------------------------------------------------
   4.  NATIVE TOAST (replaces the CSS toast when running on device)
   ------------------------------------------------------------------------ */
if (Toast && window.BillNowBT) {
  const web = window.bnToast;
  window.bnToast = msg => { Toast.show({ text: msg, duration: 'short' }).catch(() => web(msg)); };
}

})();

